#!/usr/bin/env python3
# automates link degradation for batman nodes running
# inside Linux network namespaces

import re
import sys
import time
import subprocess
import csv
import os

# Change these for changeing SRC & DST nodes and veth's that connect them
SRC = 1
DST = 2

# HH: * 5 + HH representing the mac
MAC = r"(?:[0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}"

# returns output generated by command
def run_cmd(cmd):
    print(f"[EXEC] {cmd}")

    # execute the command and capture output
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)

    # report errors
    if result.returncode != 0 and "No such file or directory" not in result.stderr:
        print(f"[ERROR] {result.stderr.strip()}")
    
    return result.stdout.strip()


def apply_degradation(netns, interface, delay_ms=0, loss_pct=0, jitter_ms=0):
    # adds synthetic network degradation to simulate real network conditions
    # uses netns for degradation inside Linux network namespaces

    tc_args = []

    # construct latency and jitter
    if delay_ms > 0:
        if jitter_ms > 0:
            tc_args.append(f"delay {delay_ms}ms {jitter_ms}ms")
        else:
            tc_args.append(f"delay {delay_ms}ms")

    # construct packet loss
    if loss_pct > 0:
        tc_args.append(f"loss {loss_pct}%")

    # exit early if no parameters
    if not tc_args:
        print(f"[INFO] No degradation parameters specified for {interface}.")
        return

    # combine arguments into single payload
    params = " ".join(tc_args)

    # clear existing queuing discipline rules to avoid conflicts
    run_cmd(f"sudo ip netns exec {netns} tc qdisc del dev {interface} root 2>/dev/null")

    # attach new netem qdisc rule to root of interface
    run_cmd(f"sudo ip netns exec {netns} tc qdisc add dev {interface} root netem {params}")

    print(f"[SUCCESS] Applied tc netem ({params}) on {interface} in {netns}")


def clear_degredation(netns, interface):
    # clears any existing network degradation on the specified interface within the given network namespace
    run_cmd(f"sudo ip netns exec {netns} tc qdisc del dev {interface} root 2>/dev/null")
    print(f"[SUCCESS] Cleared degradation rules on {interface} in {netns}")


# The originator address is the MAC of the node's main batman interface
# batctl prints it in its header, EX: MainIF/MAC: veth2-1/36:55:8e:bd:5a:a5"
def get_originator_mac(netns):
    output = run_cmd(f"sudo ip netns exec {netns} batctl o")
    match = re.search(r"MainIF/MAC:\s*\S+/(" + MAC + ")", output)
    return match.group(1).lower() if match else ""


# Applies degradation to link between nodes
def degrade_link(a, b, loss_pct):
    apply_degradation(f"vnode{a}", f"veth{a}-{b}", loss_pct=loss_pct)
    apply_degradation(f"vnode{b}", f"veth{b}-{a}", loss_pct=loss_pct)


# Clears degredation on links between nodes
def clear_link(a, b):
    clear_degredation(f"vnode{a}", f"veth{a}-{b}")
    clear_degredation(f"vnode{b}", f"veth{b}-{a}")


# Reads active route quality specifically for a target MAC or active destination
def read_active_quality(netns, target_mac):
    output = run_cmd(f"sudo ip netns exec {netns} batctl o")

    for line in output.split('\n'):
        # Match lines marked with '*' (active route)
        if not line.strip().startswith("*"):
            continue

        # Grabs every MAC on the line with originator to each hop
        macs = [m.lower()for m in re.findall(MAC, line)]
        if len(macs) <  2:
            continue

        # Skip rows that are not for the current node
        if macs[0] != target_mac:
            continue

        nexthop = macs[1]

        tq_match = re.search(r"\(\s*([\d.]+)\s*\)", line)
        tq = float(tq_match.group(1)) if tq_match else None
        if tq is not None and tq.is_integer():
            tq = int(tq)
        
        outgoing_if_match = re.search(r"\[\s*(\S+)\s*\]", line)
        outgoing_if = outgoing_if_match.group(1) if outgoing_if_match else "unknown"

        return tq, nexthop, outgoing_if

    return None, "None", "None"


def export_data(loss_levels=[10, 30, 50, 100]):
    # How long each phase lasts, in seconds (placeholders for testing)
    BASELINE_S = 30     # Time of clean link
    DEGRADE_S = 120     # Time loss is applied
    RECOVER_S = 120     # Time loss recovers
    total_s = BASELINE_S + DEGRADE_S + RECOVER_S    # Total time of experiment

    os.makedirs("TQ_EXPS", exist_ok=True)
 
    # look up the destination's originator MAC once, from the live mesh
    target_mac = get_originator_mac(f"vnode{DST}")
    print(f"[INFO] Tracking vnode{DST} at originator {target_mac} from vnode{SRC}")
    # if lookup is empty
    if not target_mac:
        raise SystemExit(f"[FATAL] Could not read bat0 MAC in vnode{DST}")
                         
    for loss_pct in loss_levels:
        filename = f"TQ_EXPS/TQ_EXP_loss{loss_pct}.csv"
        print(f"\n--- Starting TQ Experiment for {loss_pct}% Loss ---")

        curr_loss = 0   # Switch for applying loss later
        start = time.time() # When the start was
        
        with open(filename, "w", newline="") as file:
            writer = csv.writer(file)
            writer.writerow(["time_s", "TQ", "loss_pct", "nexthop", "outgoing_if"])

            elapsed = 0 # Elapsed time of exp
            while elapsed < total_s:
                # Turn loss on when the baseline phase ends
                if elapsed >= BASELINE_S and curr_loss == 0 and elapsed < BASELINE_S + DEGRADE_S:
                    degrade_link(SRC, DST, loss_pct)
                    curr_loss = loss_pct

                # Turn loss off when the damage phase ends
                if elapsed >= BASELINE_S + DEGRADE_S and curr_loss != 0:
                    clear_link(SRC, DST)
                    curr_loss = 0

                # Measure and record one row
                tq, nexthop, outgoing_if = read_active_quality(f"vnode{SRC}", target_mac)
                writer.writerow([round(elapsed, 1), tq, curr_loss, nexthop, outgoing_if])
                file.flush() # Write lagging data

                # Delay 1 second and update elapsed
                time.sleep(1)
                elapsed = time.time() - start

        print(f"[SUCCESS] Saved data to {filename}")
    
        
if __name__ == "__main__":
    print("--- Starting TQ Experiment ---")
    export_data()
    print("--- All Experiments Complete ---")